package com.teeniv.whatsapp;
import android.content.Intent;import android.os.Bundle;import android.text.Editable;import android.text.TextWatcher;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.LinearLayoutManager;import androidx.recyclerview.widget.RecyclerView;import com.google.firebase.auth.FirebaseAuth;import com.google.firebase.database.*;import java.util.*;
public class HomeActivity extends AppCompatActivity {
 ArrayList<User> all=new ArrayList<>(); UserAdapter adapter; DatabaseReference usersRef; ValueEventListener listener;
 @Override protected void onCreate(Bundle b){super.onCreate(b);if(FirebaseAuth.getInstance().getCurrentUser()==null){startActivity(new Intent(this,LoginActivity.class));finish();return;}setContentView(R.layout.activity_home);RecyclerView list=findViewById(R.id.usersList);list.setLayoutManager(new LinearLayoutManager(this));adapter=new UserAdapter(all,u->{Intent i=new Intent(this,ChatActivity.class);i.putExtra("uid",u.uid);i.putExtra("name",u.name);i.putExtra("photo",u.photoUrl==null?"":u.photoUrl);startActivity(i);});list.setAdapter(adapter);findViewById(R.id.profileButton).setOnClickListener(v->startActivity(new Intent(this,ProfileActivity.class)));findViewById(R.id.signOutButton).setOnClickListener(v->{FirebaseAuth.getInstance().signOut();startActivity(new Intent(this,LoginActivity.class));finish();});EditText search=findViewById(R.id.search);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){adapter.filter(s.toString());}public void afterTextChanged(Editable e){}});
 usersRef=FirebaseDatabase.getInstance().getReference("users");listener=usersRef.addValueEventListener(new ValueEventListener(){public void onDataChange(DataSnapshot snap){all.clear();for(DataSnapshot d:snap.getChildren()){User u=d.getValue(User.class);if(u!=null&&u.uid!=null&&!u.uid.equals(FirebaseAuth.getInstance().getUid()))all.add(u);}adapter.filter(search.getText().toString());}public void onCancelled(DatabaseError e){toast(e.getMessage());}});}
 @Override protected void onDestroy(){super.onDestroy();if(usersRef!=null&&listener!=null)usersRef.removeEventListener(listener);}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
